using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FloorWearApply {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/FloorSurfaceWear/";const string A="Assets/Afrer_Seconds/05.Model/Environment/",T=A+"Common/Textures/";static Dictionary<string,Material> created=new Dictionary<string,Material>();
 static void Textures(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(string p in Directory.GetFiles(T,"FW_*.png")){var ti=(TextureImporter)AssetImporter.GetAtPath(p.Replace('\\','/'));bool normal=p.Contains("_Normal"),linear=normal||p.Contains("MetalSmooth");ti.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;ti.sRGBTexture=!linear;ti.mipmapEnabled=true;ti.maxTextureSize=2048;ti.wrapMode=TextureWrapMode.Repeat;ti.filterMode=FilterMode.Trilinear;ti.anisoLevel=8;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.alphaSource=TextureImporterAlphaSource.FromInput;ti.SaveAndReimport();}}
 static Color Average(Texture tex){if(!tex)return Color.white;var rt=RenderTexture.GetTemporary(16,16,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear);var prev=RenderTexture.active;Texture2D cpu=null;try{Graphics.Blit(tex,rt);RenderTexture.active=rt;cpu=new Texture2D(16,16,TextureFormat.RGBA32,false,true);cpu.ReadPixels(new Rect(0,0,16,16),0,0);cpu.Apply();var a=cpu.GetPixels();return new Color(a.Average(c=>c.r),a.Average(c=>c.g),a.Average(c=>c.b),1);}finally{RenderTexture.active=prev;if(cpu)UnityEngine.Object.DestroyImmediate(cpu);RenderTexture.ReleaseTemporary(rt);}}
 static Material Mat(Material original,string floor,int kind){string suffix=kind==1?floor:kind==2?"CargoFloor":kind==3?"CargoWall":"CargoEdge";string key="FW_"+floor+"_"+suffix+"_"+original.name; if(created.TryGetValue(key,out var ready))return ready;string path=A+floor+"/Materials/"+key+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(original){name=key};var color=original.GetColor("_BaseColor");var avg=Average(original.GetTexture("_BaseMap"));color=new Color(color.r*avg.r/0.807f,color.g*avg.g/0.807f,color.b*avg.b/0.807f,color.a);m.SetColor("_BaseColor",color);m.SetColor("_Color",color);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(T+"FW_"+suffix+"_Base.png"));m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(T+"FW_"+suffix+"_Normal.png"));m.SetFloat("_BumpScale",kind==1?.32f:.50f);m.EnableKeyword("_NORMALMAP");m.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(T+"FW_"+suffix+"_MetalSmooth.png"));m.EnableKeyword("_METALLICSPECGLOSSMAP");m.SetFloat("_Metallic",1);m.SetFloat("_Smoothness",1);m.SetFloat("_SmoothnessTextureChannel",0);m.DisableKeyword("_SMOOTHNESS_TEXTURE_ALBEDO_CHANNEL_A");m.SetTextureScale("_BaseMap",Vector2.one);m.SetTextureOffset("_BaseMap",Vector2.zero);AssetDatabase.CreateAsset(m,path);}created[key]=m;return m;}
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string original=SceneManager.GetActiveScene().path;Textures();var plan=JObject.Parse(File.ReadAllText(H+"targets.json"));var log=new List<object>();try{foreach(string floor in new[]{"B5","B4"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+floor+"_Circular.unity");float ground=floor=="B5"?-82:-66;int serial=0;foreach(var r in plan[floor]){GlobalObjectId.TryParse((string)r["id"],out var id);var rr=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id) as MeshRenderer;if(!rr)throw new Exception("Missing renderer "+r["name"]);var mf=rr.GetComponent<MeshFilter>();var old=mf.sharedMesh;if(AssetDatabase.GetAssetPath(old).Contains("/FW_"))throw new Exception("Already applied: "+rr.name);var verts=old.vertices;var norms=old.normals;var uvs=old.uv;var uv2=old.uv2;var colors=old.colors;var tangents=old.tangents;var world=verts.Select(v=>rr.transform.TransformPoint(v)).ToArray();var ms=rr.sharedMaterials;var newMats=ms.ToList();var buckets=new List<List<int>>();for(int i=0;i<old.subMeshCount;i++)buckets.Add(new List<int>());var newv=new List<Vector3>();var newn=new List<Vector3>();var newuv=new List<Vector2>();var newuv2=new List<Vector2>();var newc=new List<Color>();var newtan=new List<Vector4>();var vertexMap=new Dictionary<long,int>();var subMap=new Dictionary<int,int>();int count=0;bool cargo=(bool)r["cargo"];
 int Vertex(int vi,int kind,int axis){long k=(long)vi*100+kind*10+axis;if(vertexMap.TryGetValue(k,out int existing))return existing;int n=newv.Count;vertexMap[k]=n;newv.Add(verts[vi]);newn.Add(norms[vi]);Vector2 uv=uvs.Length==verts.Length?uvs[vi]:Vector2.zero;if(kind==1)uv=new Vector2(world[vi].x,world[vi].z)*.25f;else if(kind==2)uv=new Vector2((world[vi].x-44+2)/4,(world[vi].z-28+3.25f)/4);else if(kind>=3){float yy=world[vi].y-ground;if(yy>15.9f)yy-=16;float xx=axis==0?world[vi].z-28:world[vi].x-44;uv=new Vector2((xx+2)/4,yy/4);}newuv.Add(uv);if(uv2.Length==verts.Length)newuv2.Add(uv2[vi]);if(colors.Length==verts.Length)newc.Add(colors[vi]);if(tangents.Length==verts.Length)newtan.Add(tangents[vi]);return n;}
 for(int sub=0;sub<old.subMeshCount;sub++){var ix=old.GetTriangles(sub);var mat=ms[sub];for(int j=0;j<ix.Length;j+=3){int ia=ix[j],ib=ix[j+1],ic=ix[j+2];var center=(world[ia]+world[ib]+world[ic])/3;var norm=Vector3.Cross(world[ib]-world[ia],world[ic]-world[ia]).normalized;int kind=0,axis=Mathf.Abs(norm.x)>Mathf.Abs(norm.z)?0:1;string name=mat.name;bool paint=name.Contains("Floor")||name.Contains("Shell")||name.Contains("Coat");if(!cargo&&paint&&norm.y>.93f&&Mathf.Abs(center.y-ground)<.13f)kind=1;
 if(cargo){float yy=center.y-ground;if(yy>15.9f)yy-=16;bool surface=name.Contains("Steel")||name.Contains("Coat")||name.Contains("Powder");if(surface&&norm.y>.90f&&yy<.15f&&yy>-.02f)kind=2;else if(surface&&Mathf.Abs(norm.y)<.55f&&yy<3.4f&&yy>.10f)kind=name.Contains("Steel")?4:3;}
 int dest=sub;if(kind>0){int key=sub*10+kind;if(!subMap.TryGetValue(key,out dest)){dest=buckets.Count;subMap[key]=dest;buckets.Add(new List<int>());newMats.Add(Mat(mat,floor,kind));}count++;}buckets[dest].Add(Vertex(ia,kind,axis));buckets[dest].Add(Vertex(ib,kind,axis));buckets[dest].Add(Vertex(ic,kind,axis));}}
 if(count==0){log.Add(new{floor,name=rr.name,changedTriangles=0,mesh="",triangles=old.triangles.Length/3});continue;}var mesh=new Mesh{name="FW_"+floor+"_Surface_"+(++serial).ToString("000"),indexFormat=newv.Count>65535?IndexFormat.UInt32:IndexFormat.UInt16};mesh.SetVertices(newv);mesh.SetNormals(newn);mesh.SetUVs(0,newuv);if(newuv2.Count>0)mesh.SetUVs(1,newuv2);if(newc.Count>0)mesh.SetColors(newc);mesh.subMeshCount=buckets.Count;for(int i=0;i<buckets.Count;i++)mesh.SetTriangles(buckets[i],i,false);mesh.RecalculateBounds();mesh.RecalculateTangents();string mp=A+floor+"/"+mesh.name+".asset";AssetDatabase.CreateAsset(mesh,mp);mf.sharedMesh=mesh;rr.sharedMaterials=newMats.ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(mf);PrefabUtility.RecordPrefabInstancePropertyModifications(rr);log.Add(new{floor,name=rr.name,changedTriangles=count,mesh=mp,triangles=mesh.triangles.Length/3});}
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}AssetDatabase.SaveAssets();}finally{EditorSceneManager.OpenScene(original);}File.WriteAllText(H+"applied.json",JsonConvert.SerializeObject(log,Formatting.Indented));return new{renderers=log.Count,materials=created.Count};}
}
